package com.example.editor.metamodel.importing.updatesite;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;

/** Extracts named EVL/OCL validation rules and EOL operations as non-executing semantic drafts. */
@Component
public class UpdateSiteScriptSemanticRecovery {
    private static final Pattern EVL=Pattern.compile("(?is)context\\s+([A-Za-z_][\\w.:]*)\\s*\\{.*?\\b(constraint|critique)\\s+([A-Za-z_][\\w]*)\\s*\\{");
    private static final Pattern OCL=Pattern.compile("(?im)^\\s*context\\s+([A-Za-z_][\\w.:]*)\\s+inv(?:\\s+([A-Za-z_][\\w]*))?\\s*:");
    private static final Pattern EOL=Pattern.compile("(?im)^\\s*operation\\s+(?:([A-Za-z_][\\w.:]*)\\s+)?([A-Za-z_][\\w]*)\\s*\\(");

    /** Descripción: Ejecuta la operación «recover» correspondiente a la responsabilidad de UpdateSiteScriptSemanticRecovery. Entradas: path: ruta o ubicación utilizada por la operación; kind: dato de entrada necesario para la operación; content: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ List<UpdateSiteSemanticElementDraft> recover(String path,UpdateSiteArtifactKind kind,byte[] content){String text=new String(content,StandardCharsets.UTF_8);return switch(kind){case EVL->evl(path,text);case OCL->ocl(path,text);case EOL->eol(path,text);default->List.of();};}
    /** Descripción: Ejecuta la operación «evl» correspondiente a la responsabilidad de UpdateSiteScriptSemanticRecovery. Entradas: path: ruta o ubicación utilizada por la operación; text: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private List<UpdateSiteSemanticElementDraft> evl(String path,String text){List<UpdateSiteSemanticElementDraft> result=new ArrayList<>();Matcher matcher=EVL.matcher(text);while(matcher.find()){String context=matcher.group(1);String name=matcher.group(3);result.add(validation(path,"evl",context,name,"EVL "+matcher.group(2).toLowerCase(Locale.ROOT)+" recovered without executing the script."));}return List.copyOf(result);}
    /** Descripción: Ejecuta la operación «ocl» correspondiente a la responsabilidad de UpdateSiteScriptSemanticRecovery. Entradas: path: ruta o ubicación utilizada por la operación; text: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private List<UpdateSiteSemanticElementDraft> ocl(String path,String text){List<UpdateSiteSemanticElementDraft> result=new ArrayList<>();Matcher matcher=OCL.matcher(text);int anonymous=1;while(matcher.find()){String name=matcher.group(2)==null?"Invariant"+anonymous++:matcher.group(2);result.add(validation(path,"ocl",matcher.group(1),name,"OCL invariant recovered without evaluating the expression."));}return List.copyOf(result);}
    /** Descripción: Ejecuta la operación «eol» correspondiente a la responsabilidad de UpdateSiteScriptSemanticRecovery. Entradas: path: ruta o ubicación utilizada por la operación; text: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private List<UpdateSiteSemanticElementDraft> eol(String path,String text){List<UpdateSiteSemanticElementDraft> result=new ArrayList<>();Matcher matcher=EOL.matcher(text);while(matcher.find()){String owner=matcher.group(1)==null?"Any":matcher.group(1);String name=matcher.group(2);result.add(new UpdateSiteSemanticElementDraft(stable("eol-operation:"+owner+":"+name),UpdateSiteSemanticKind.COMMAND,name,"",path,"EOL",UpdateSiteConfidence.RECOVERED,true,"HYDRA operation/action draft","EOL operation signature recovered statically; the body is preserved as source evidence and is never executed during import.",List.of("Operation behavior requires explicit review before runtime use.")));}return List.copyOf(result);}
    /** Descripción: Ejecuta la operación «validation» correspondiente a la responsabilidad de UpdateSiteScriptSemanticRecovery. Entradas: path: ruta o ubicación utilizada por la operación; language: dato de entrada necesario para la operación; context: dato de entrada necesario para la operación; name: dato de entrada necesario para la operación; purpose: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private UpdateSiteSemanticElementDraft validation(String path,String language,String context,String name,String purpose){return new UpdateSiteSemanticElementDraft(stable(language+":"+context+":"+name),UpdateSiteSemanticKind.VALIDATION,name,"",path,language.toUpperCase(Locale.ROOT),UpdateSiteConfidence.RECOVERED,true,"HYDRA validation draft",purpose,List.of("Recovered rule expression must be reviewed before activation."));}
    /** Descripción: Ejecuta la operación «stable» correspondiente a la responsabilidad de UpdateSiteScriptSemanticRecovery. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private String stable(String value){String normalized=value.replaceAll("[^A-Za-z0-9._:-]","-");return normalized.length()>180?normalized.substring(0,180):normalized;}
}
